{"command": "cd ~/captures; python3 -c "
from PIL import Image
im=Image.open('top_001.png').convert('L')
w,h=im.size
px=im.load()
# threshold dark
import sys
sys.setrecursionlimit(10000)
th=int(sys.argv[1]) if len(sys.argv)>1 else 80
seen=[[False]*w for _ in range(h)]
blobs=[]
from collections import deque
for y in range(0,h,2):
  for x in range(0,w,2):
    if seen[y][x]: continue
    if px[x,y]<th:
      q=deque([(x,y)]); seen[y][x]=True
      pts=[]
      while q:
        cx,cy=q.popleft(); pts.append((cx,cy))
        for dx,dy in ((2,0),(-2,0),(0,2),(0,-2)):
          nx,ny=cx+dx,cy+dy
          if 0<=nx<w and 0<=ny<h and not seen[ny][nx] and px[nx,ny]<th:
            seen[ny][nx]=True; q.append((nx,ny))
      if len(pts)>30:
        xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
        blobs.append((len(pts),sum(xs)/len(xs),sum(ys)/len(ys),min(xs),max(xs),min(ys),max(ys)))
blobs.sort(reverse=True)
for b in blobs[:20]: print(b)
""}

